package com.mssclient.ui;

import com.mssclient.auth.AuthService; import com.mssclient.config.*; import com.mssclient.crash.CrashReporter; import com.mssclient.game.LauncherService; import com.mssclient.mods.ModManager; import com.mssclient.update.UpdateService;
import javafx.animation.FadeTransition; import javafx.geometry.Insets; import javafx.scene.Parent; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.util.Duration;

/** JavaFX shell with animated dark UI, profiles, modules, news, Discord, logs, and launch controls. */
public final class MainView {
    private final ProfileStore profiles; private final AuthService auth; private final ModManager mods; private final LauncherService launcher; private final UpdateService updates; private final Label status = new Label("Ready");
    public MainView(ProfileStore profiles, AuthService auth, ModManager mods, LauncherService launcher, UpdateService updates) { this.profiles = profiles; this.auth = auth; this.mods = mods; this.launcher = launcher; this.updates = updates; }
    public Parent create() { var root = new BorderPane(); root.getStyleClass().add("root-shell"); root.setPadding(new Insets(24)); root.setTop(header()); root.setCenter(center()); root.setBottom(status); fade(root); return root; }
    private Parent header() { var title = new Label("MSS CLIENT"); title.getStyleClass().add("title"); var discord = new Button("Discord"); discord.setOnAction(e -> showStatus("Discord RPC/link integration ready.")); var login = new Button("Microsoft Login"); login.setOnAction(e -> showStatus("Logged in as " + auth.beginMicrosoftLogin().username())); var offline = new Button("Offline Mode"); offline.setOnAction(e -> showStatus("Offline session: " + auth.offline("Player").username())); return new HBox(16, title, spacer(), login, offline, discord); }
    private Parent center() { var tabs = new TabPane(); tabs.getTabs().add(tab("Launch", launchPane())); tabs.getTabs().add(tab("Right Shift GUI", modulePane())); tabs.getTabs().add(tab("Mods & Profiles", modsPane())); tabs.getTabs().add(tab("News", newsPane())); tabs.getTabs().add(tab("Logs", logsPane())); return tabs; }
    private Parent launchPane() { var p = profiles.selected(); var box = card(); var low = check("Low-memory mode", p.isLowMemoryMode(), p::setLowMemoryMode); var fps = check("PvP FPS Boost", p.isFpsBoost(), p::setFpsBoost); var launch = new Button("Launch Minecraft"); launch.getStyleClass().add("primary"); launch.setOnAction(e -> { var plan = launcher.launch(); showStatus("Launch plan: " + plan.version() + " / " + plan.account() + " / " + plan.jvmArgs()); }); box.getChildren().addAll(new Label("Selected profile: " + p.getName()), fps, low, launch, new ProgressBar(.72)); return box; }
    private Parent modulePane() { var columns = new HBox(16); for (ModuleCategory c : ModuleCategory.values()) { var box = card(); box.getChildren().add(new Label(c.name())); for (ClientModule m : ClientModule.values()) if (m.category() == c) box.getChildren().add(check(m.displayName(), profiles.selected().getModules().contains(m), enabled -> profiles.selected().toggleModule(m, enabled))); columns.getChildren().add(box); } return columns; }
    private Parent modsPane() { var p = profiles.selected(); var box = card(); box.getChildren().addAll(check("OptiFine (1.8.9)", p.isOptifine(), p::setOptifine), check("Sodium (1.21+)", p.isSodium(), p::setSodium), check("Lithium (1.21+)", p.isLithium(), p::setLithium), check("FerriteCore (1.21+)", p.isFerriteCore(), p::setFerriteCore)); var export = new Button("Export Modpack"); export.setOnAction(e -> showStatus(mods.exportModpack(p))); box.getChildren().add(export); return box; }
    private Parent newsPane() { return card(new Label("News: MSS CLIENT alpha generated. Automatic update checks are enabled."), new Label("Discord: rich presence/link hooks are prepared for Windows builds.")); }
    private Parent logsPane() { var area = new TextArea(CrashReporter.logs()); area.setPromptText("Crash reports and launcher logs appear here."); area.setPrefRowCount(18); return card(area); }
    private CheckBox check(String text, boolean selected, java.util.function.Consumer<Boolean> action) { var cb = new CheckBox(text); cb.setSelected(selected); cb.setOnAction(e -> action.accept(cb.isSelected())); return cb; }
    private Tab tab(String name, Parent content) { var tab = new Tab(name, content); tab.setClosable(false); return tab; }
    private VBox card(javafx.scene.Node... children) { var box = new VBox(14, children); box.getStyleClass().add("glass-card"); box.setPadding(new Insets(20)); return box; }
    private Pane spacer() { var p = new Pane(); HBox.setHgrow(p, Priority.ALWAYS); return p; }
    private void fade(Parent p) { var ft = new FadeTransition(Duration.millis(450), p); ft.setFromValue(0); ft.setToValue(1); ft.play(); }
    public void showStatus(String message) { status.setText(message); CrashReporter.record(message); }
}
